def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys[i]=values[i] on the defaults mode=fast, level=3 and return
    mode, level, then the other keys' values in the order given."""
    pre keys.len() == values.len()
    post out.len() >= 2
    ex settings(["level", "color"], ["5", "red"]) == ["fast", "5", "red"]
    ex settings(["mode"], ["slow"]) == ["slow", "3"]
    ex settings([], []) == ["fast", "3"]
    d: dict[str, str] = {"mode": "fast", "level": "3"}
    for i in range(keys.len()):
        d[keys[i]] = values[i]
    res: list[str] = [d.get("mode") else "fast", d.get("level") else "3"]
    for k, v in d.items():
        if k != "mode" and k != "level":
            res.append(v.copy())
    return res
